// Runs once per webhook call. Only the fields named below reach the PDF, so a
// new or renamed key in the payload cannot break the layout. Change the
// field names and the HTML to match your payload.
const body = $json.body ?? {};
const customer = body.customer ?? {};
const address = customer.address ?? {};
const items = Array.isArray(body.items) ? body.items : [];
const currency = body.currency ?? 'EUR';

const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const money = (n) => Number(n || 0).toFixed(2);
const lineTotal = (it) => Number(it.qty || 0) * Number(it.unit_price || 0);
const total = items.reduce((sum, it) => sum + lineTotal(it), 0);

const rows = items
  .map(
    (it) => `<tr><td>${esc(it.name)}</td><td class="num">${esc(it.qty)}</td>` +
      `<td class="num">${money(it.unit_price)}</td><td class="num">${money(lineTotal(it))}</td></tr>`,
  )
  .join('\n');

const html = `<!doctype html>
<html><head><meta charset="utf-8"><style>
@page { size: A4; margin: 20mm;
  @bottom-center { content: "Page " counter(page) " of " counter(pages); font: 8pt sans-serif; color: #6b7480 } }
body { font: 10.5pt/1.5 "DejaVu Sans", sans-serif; color: #1c2024 }
h1 { font-size: 18pt; margin: 0 0 4mm }
.meta { color: #6b7480; margin-bottom: 8mm }
table { width: 100%; border-collapse: collapse; margin-top: 6mm }
th { text-align: left; border-bottom: 2px solid #1c2024; padding: 2mm 0 }
td { padding: 2.5mm 0; border-bottom: 1px solid #e3e6ea }
.num { text-align: right }
tfoot td { font-weight: bold; border-bottom: none }
thead { display: table-header-group }
tr { break-inside: avoid }
</style></head><body>
<h1>Order ${esc(body.order_id)}</h1>
<p class="meta">${esc(body.created_at)}</p>
<p><strong>${esc(customer.name)}</strong><br>
${esc(address.street)}<br>${esc(address.postal_code)} ${esc(address.city)}<br>${esc(address.country)}</p>
<table>
  <thead><tr><th>Item</th><th class="num">Qty</th><th class="num">Unit price</th><th class="num">Amount</th></tr></thead>
  <tbody>
${rows}
  </tbody>
  <tfoot><tr><td colspan="3">Total (${esc(currency)})</td><td class="num">${money(total)}</td></tr></tfoot>
</table>
${body.notes ? `<p>${esc(body.notes)}</p>` : ''}
</body></html>`;

const id = String(body.order_id ?? 'document').replace(/[^A-Za-z0-9_-]/g, '_');
return {
  json: {
    html,
    filename: `order-${id}.pdf`,
    email_to: customer.email ?? '',
    customer_name: customer.name ?? '',
    subject: `Your order ${body.order_id ?? ''}`.trim(),
  },
};
